<?php require_once 'config/app.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=stmt($conn,'SELECT id,full_name,email,password,role FROM users WHERE email=?','s',[$email]);$u=$s->get_result()->fetch_assoc();if($u&&password_verify($pass,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['full_name']=$u['full_name'];$_SESSION['email']=$u['email'];$_SESSION['role']=$u['role'];redirect($u['role']==='admin'?'admin/dashboard.php':'customer/dashboard.php');}$error='Email or password is incorrect.';}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | AutoCare</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><div class="auth-side"><div class="auth-brand">Auto<span>Care</span></div><h1>Service smarter.<br>Drive happier.</h1><p>Your complete automotive service management workspace. Book appointments, manage vehicles and keep every service organized.</p></div><div class="auth-box"><form class="auth-card" method="post"><h2>Welcome back</h2><p>Sign in to continue to AutoCare.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['registered'])):?><div class="alert success">Account created successfully. Please sign in.</div><?php endif;?><?php if(isset($_GET['admin_created'])):?><div class="alert success">Administrator created. Sign in and delete setup_admin.php.</div><?php endif;?><div class="field"><label>Email address</label><input type="email" name="email" autocomplete="username" required></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required></div><button class="btn">Sign in to account</button><div class="auth-bottom">New to AutoCare? <a href="register.php">Create customer account</a></div></form></div></body></html>
